record.field:
async def execute(task_id, module_name, usecase):
    """Länka modul + use case till task (om fälten finns)."""
    task = env['project.task'].sudo().browse(int(task_id))
    if not task.exists():
        return 'Task %s not found' % task_id
    vals = {}
    if 'ai_plan' in task._fields:
        vals['ai_plan'] = 'Modul: %s\n\n%s' % (module_name, usecase)
    if 'ai_usecase' in task._fields:
        vals['ai_usecase'] = '<p>%s — <b>%s</b></p>' % (usecase, module_name)
    if not vals:
        return 'ai_plan/ai_usecase-fält saknas (installera project_ai_plan)'
    task.write(vals)
    return 'Task %s kopplad till modul %s' % (task.name, module_name)

async def execute(task_id, description=None, priority=None):
    """Uppdatera beskrivning/prioritet på task."""
    task = env['project.task'].sudo().browse(int(task_id))
    if not task.exists():
        return 'Task %s not found' % task_id
    vals = {}
    if description is not None:
        vals['description'] = str(description)
    if priority is not None:
        vals['priority'] = int(priority)
    if not vals:
        return 'Inga fält att uppdatera'
    task.write(vals)
    return 'Task %s uppdaterad' % task.name
